/**
 * Compatibility declarations for the legacy generated type files.
 *
 * Runtime clients are generated by ts-proto/nice-grpc under `static/`; these
 * declarations keep the old per-message imports type-only until all adapters
 * have moved to the consolidated generated modules.
 */
export type Long = number | string;

export interface EnumTypeDefinition {
  readonly format?: string;
}

export interface MessageTypeDefinition<Input, Output> {
  readonly format?: string;
  readonly input?: Input;
  readonly output?: Output;
}

export interface MethodDefinition<Input, Output, InputOutput, OutputOutput> {
  readonly path: string;
  readonly requestStream: boolean;
  readonly responseStream: boolean;
  readonly requestSerialize: (value: Input) => Buffer;
  readonly requestDeserialize: (value: Buffer) => InputOutput;
  readonly responseSerialize: (value: Output) => Buffer;
  readonly responseDeserialize: (value: Buffer) => OutputOutput;
}
